-- بوابة العيادات الخارجية - الأساس الأمني
create type public.portal_role as enum ('management','staff','custom');
create type public.service_key as enum ('patient_experience','external_referrals');
create table public.departments(id bigint generated by default as identity primary key,name_ar text not null,name_en text,is_active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete restrict,name text not null,email text,role public.portal_role not null default 'staff',department_id bigint references public.departments(id) on delete set null,must_change_password boolean not null default false,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_service_access(id bigint generated by default as identity primary key,user_id uuid not null references public.profiles(id) on delete cascade,service_key public.service_key not null,can_view boolean not null default false,can_create boolean not null default false,can_edit boolean not null default false,can_manage boolean not null default false,unique(user_id,service_key));
create table public.audit_log(id bigint generated by default as identity primary key,actor_user_id uuid references public.profiles(id) on delete set null,service_key public.service_key,action text not null,entity_type text not null,entity_id text,old_data jsonb,new_data jsonb,created_at timestamptz not null default now());
alter table public.departments enable row level security;alter table public.profiles enable row level security;alter table public.user_service_access enable row level security;alter table public.audit_log enable row level security;
create or replace function public.is_management() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='management' and p.is_active=true);$$;
create policy "active users read own profile" on public.profiles for select to authenticated using (id=auth.uid() or public.is_management());
create policy "management manages profiles" on public.profiles for all to authenticated using (public.is_management()) with check (public.is_management());
create policy "authenticated read active departments" on public.departments for select to authenticated using (is_active or public.is_management());
create policy "management manages departments" on public.departments for all to authenticated using (public.is_management()) with check (public.is_management());
create policy "users read own service access" on public.user_service_access for select to authenticated using (user_id=auth.uid() or public.is_management());
create policy "management manages service access" on public.user_service_access for all to authenticated using (public.is_management()) with check (public.is_management());
create policy "management reads audit log" on public.audit_log for select to authenticated using (public.is_management());
-- No client INSERT policy for audit_log. Sensitive audit events should be written by trusted server-side functions/Edge Functions.
